const rules=$input.all().map(i=>i.json);
const actions=[];
for(const r of rules){
  const fp=parseFloat(r.fp_rate);
  if(fp>=30) actions.push({rule_id:r.rule_id,action:'SUPPRESS',reason:`FP rate ${fp}% exceeds 30% threshold`,fp_rate:fp,total:r.total_alerts});
  else if(fp>=15) actions.push({rule_id:r.rule_id,action:'RAISE_THRESHOLD',reason:`FP rate ${fp}% — raise confidence to ${Math.min(95,75+10)}%`,fp_rate:fp,new_threshold:Math.min(95,75+10),total:r.total_alerts});
  else if(fp<=3&&parseInt(r.total_alerts)>=10) actions.push({rule_id:r.rule_id,action:'LOWER_THRESHOLD',reason:`Only ${fp}% FP — can lower threshold to catch more`,fp_rate:fp,new_threshold:Math.max(60,75-10),total:r.total_alerts});
}
return[{json:{actions,suppressed:actions.filter(a=>a.action==='SUPPRESS').length,raised:actions.filter(a=>a.action==='RAISE_THRESHOLD').length,lowered:actions.filter(a=>a.action==='LOWER_THRESHOLD').length,total_rules_analysed:rules.length,analysed_at:new Date().toISOString()}}];

